// 1. Dữ liệu đối soát là dữ liệu nghiệp vụ: ghi vào DB, không suy ra từ log
PaymentResult capture(Order order) {
    // ghi PENDING trước (transaction ngắn), không giữ transaction trong lúc gọi cổng thanh toán
    PaymentRecord record = paymentRecords.save(PaymentRecord.pending(order));
    PaymentResult result = gateway.capture(order, record.idempotencyKey());
    paymentRecords.markCaptured(record.id(), result.transactionId());   // nguồn đối soát
    log.info("Payment captured order={} txn={}", order.id(), result.transactionId());
    return result;
}

<!-- 2. Log ứng dụng: chọn rõ ràng giữa mất dòng và chặn thread -->
<appender name="ASYNC_FILE" class="ch.qos.logback.classic.AsyncAppender">
  <queueSize>8192</queueSize>
  <discardingThreshold>0</discardingThreshold>  <!-- không bỏ INFO -->
  <neverBlock>false</neverBlock>                <!-- đầy thì chặn, không mất -->
  <appender-ref ref="FILE"/>
</appender>
